#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/uaccess.h>
#include <linux/interrupt.h>
#include <linux/wait.h>
#include <linux/spinlock.h>
#include <linux/string.h>

#define DEVICE_NAME "irqchardev"
#define BUF_SIZE    64

static int irq_num = 0;
module_param(irq_num, int, 0444);
MODULE_PARM_DESC(irq_num, "IRQ number to request");

static dev_t dev_num;
static struct cdev my_cdev;

static DECLARE_WAIT_QUEUE_HEAD(data_wq);
static DEFINE_SPINLOCK(data_lock);
static int data_ready;
static char data_buf[BUF_SIZE];
static int data_len;

static irqreturn_t mydev_irq_handler(int irq, void *dev_id)
{
	unsigned long flags;

	spin_lock_irqsave(&data_lock, flags);
	data_len = scnprintf(data_buf, sizeof(data_buf), "irq=%d\n", irq);
	WRITE_ONCE(data_ready, 1);
	spin_unlock_irqrestore(&data_lock, flags);

	wake_up_interruptible(&data_wq);
	return IRQ_HANDLED;
}

static int mydev_open(struct inode *inode, struct file *file)
{
	return 0;
}

static int mydev_release(struct inode *inode, struct file *file)
{
	return 0;
}

static ssize_t mydev_read(struct file *file, char __user *buf,
			  size_t count, loff_t *offset)
{
	int ret;
	unsigned long flags;
	size_t len;
	char snapshot[BUF_SIZE];

	if (!count)
		return 0;

	for (;;) {
		ret = wait_event_interruptible(data_wq,
					       READ_ONCE(data_ready) != 0);
		if (ret)
			return ret;

		spin_lock_irqsave(&data_lock, flags);

		/* Another reader may have consumed the data while we waited. */
		if (!data_ready) {
			spin_unlock_irqrestore(&data_lock, flags);
			continue;
		}

		len = min_t(size_t, count, data_len);
		memcpy(snapshot, data_buf, len);
		WRITE_ONCE(data_ready, 0);
		spin_unlock_irqrestore(&data_lock, flags);
		break;
	}

	/* User access may sleep; use the snapshot outside the spinlock. */
	if (copy_to_user(buf, snapshot, len))
		return -EFAULT;

	return len;
}

static const struct file_operations fops = {
	.owner   = THIS_MODULE,
	.open    = mydev_open,
	.release = mydev_release,
	.read    = mydev_read,
};

