#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <sys/ioctl.h>
#include <unistd.h>

#include <linux/spi/spidev.h>

int main(void)
{
	int fd;
	int ret = 1;
	int transferred;
	uint8_t mode = SPI_MODE_0;
	uint8_t bpw = 8;
	uint32_t speed = 1000000;
	uint8_t tx[4] = {0xAA, 0xBB, 0xCC, 0xDD};
	uint8_t rx[4] = {0};
	struct spi_ioc_transfer tr = {
		.tx_buf = (uintptr_t)tx,
		.rx_buf = (uintptr_t)rx,
		.len = sizeof(tx),
		.speed_hz = speed,
		.bits_per_word = bpw,
	};

	fd = open("/dev/spidev0.0", O_RDWR);
	if (fd < 0) {
		perror("open /dev/spidev0.0");
		return 1;
	}

	if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
		perror("SPI_IOC_WR_MODE");
		goto out_close;
	}
	if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bpw) < 0) {
		perror("SPI_IOC_WR_BITS_PER_WORD");
		goto out_close;
	}
	if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
		perror("SPI_IOC_WR_MAX_SPEED_HZ");
		goto out_close;
	}

	transferred = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
	if (transferred < 0) {
		perror("SPI_IOC_MESSAGE");
		goto out_close;
	}
	if ((size_t)transferred != sizeof(tx)) {
		fprintf(stderr, "SPI_IOC_MESSAGE: transferred %d of %zu bytes\n",
			transferred, sizeof(tx));
		goto out_close;
	}

	printf("rx: %02x %02x %02x %02x\n", rx[0], rx[1], rx[2], rx[3]);
	ret = 0;

out_close:
	close(fd);
	return ret;
}

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <systemd/sd-bus.h>

static int method_ping(sd_bus_message *m, void *userdata, sd_bus_error *ret_error)
{
	const char *greeting = NULL;
	char reply[256];
	int r;

	(void)userdata;
	(void)ret_error;

	r = sd_bus_message_read(m, "s", &greeting);
	if (r < 0) {
		fprintf(stderr, "sd_bus_message_read failed: %s\n", strerror(-r));
		return r;
	}

	snprintf(reply, sizeof(reply), "pong: %s", greeting ? greeting : "");
	return sd_bus_reply_method_return(m, "s", reply);
}

static const sd_bus_vtable example_vtable[] = {
	SD_BUS_VTABLE_START(0),
	SD_BUS_METHOD("Ping", "s", "s", method_ping, SD_BUS_VTABLE_UNPRIVILEGED),
	SD_BUS_VTABLE_END,
};

int main(void)
{
	sd_bus *bus = NULL;
	sd_bus_slot *slot = NULL;
	int r;

	r = sd_bus_open_system(&bus);
	if (r < 0) {
		fprintf(stderr, "sd_bus_open_system failed: %s\n", strerror(-r));
		goto finish;
	}

	r = sd_bus_add_object_vtable(bus, &slot, "/com/embedeval/Example",
				     "com.embedeval.Example", example_vtable,
				     NULL);
	if (r < 0) {
		fprintf(stderr, "sd_bus_add_object_vtable failed: %s\n",
			strerror(-r));
		goto finish;
	}

	r = sd_bus_request_name(bus, "com.embedeval.Example", 0);
	if (r < 0) {
		fprintf(stderr, "sd_bus_request_name failed: %s\n", strerror(-r));
		goto finish;
	}

	for (;;) {
		r = sd_bus_process(bus, NULL);
		if (r < 0) {
			fprintf(stderr, "sd_bus_process failed: %s\n",
				strerror(-r));
			goto finish;
		}
		if (r > 0)
			continue; /* more work queued — drain */
		r = sd_bus_wait(bus, (uint64_t)-1);
		if (r < 0) {
