/*
 * Spinlock-protected shared state between ISR and thread.
 * Keep ISR work bounded and perform logging in thread context.
 */

#include <stdint.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/printk.h>

static struct k_spinlock counter_lock;
static uint32_t shared_counter;

/* Simulated ISR: update shared state without blocking I/O. */
static void isr_handler(const void *arg)
{
	ARG_UNUSED(arg);
	k_spinlock_key_t key;

	key = k_spin_lock(&counter_lock);
	shared_counter++;
	k_spin_unlock(&counter_lock, key);
}

/* Reader thread: snapshot under the spinlock, then log after unlocking. */
static void reader_thread(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	for (int i = 0; i < 5; i++) {
		k_spinlock_key_t key;
		uint32_t val;

		key = k_spin_lock(&counter_lock);
		val = shared_counter;
		k_spin_unlock(&counter_lock, key);

		printk("counter=%u\n", (unsigned int)val);
		k_sleep(K_MSEC(100));
	}
}

K_THREAD_DEFINE(reader_tid, 1024,
		reader_thread, NULL, NULL, NULL,
		5, 0, 0);

int main(void)
{
	/* Simulate ISR firing 5 times. */
	isr_handler(NULL);
	isr_handler(NULL);
	isr_handler(NULL);
	isr_handler(NULL);
	isr_handler(NULL);

	/* Allow reader thread to observe counter. */
	k_sleep(K_MSEC(600));

	return 0;
}

/*
 * Lock-free SPSC ring queue for Zephyr RTOS.
 * Exactly one producer and one consumer may access the queue.
 */

#include <stdint.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/barrier.h>

#define QUEUE_SIZE 16U /* MUST be power of 2 */
#define QUEUE_MASK (QUEUE_SIZE - 1U)

struct spsc_queue {
	uint8_t buf[QUEUE_SIZE];
	atomic_t write_idx;
	atomic_t read_idx;
};

static struct spsc_queue q;

static int spsc_push(struct spsc_queue *q, uint8_t val)
{
	/* Unsigned arithmetic makes counter wraparound well-defined. */
	uint32_t w = (uint32_t)atomic_get(&q->write_idx);
	uint32_t r = (uint32_t)atomic_get(&q->read_idx);

	/* Unmasked counters allow all QUEUE_SIZE slots to be used. */
	if ((uint32_t)(w - r) >= QUEUE_SIZE) {
		return -1;
	}

	/* Acquire the consumer's progress before reusing a slot. */
	barrier_dmem_fence_full();

	q->buf[w & QUEUE_MASK] = val;

	/* Publish the payload before advancing the write index. */
	barrier_dmem_fence_full();
	atomic_set(&q->write_idx, (atomic_val_t)(uint32_t)(w + 1U));

	return 0;
}

static int spsc_pop(struct spsc_queue *q, uint8_t *val)
{
	uint32_t r = (uint32_t)atomic_get(&q->read_idx);
	uint32_t w = (uint32_t)atomic_get(&q->write_idx);

	if (r == w) {
		return -1;
	}

	/* Acquire the published payload before reading it. */
	barrier_dmem_fence_full();

	*val = q->buf[r & QUEUE_MASK];

	/* Finish reading before allowing the producer to reuse the slot. */
	barrier_dmem_fence_full();
	atomic_set(&q->read_idx, (atomic_val_t)(uint32_t)(r + 1U));

	return 0;
}

int main(void)
{
	uint8_t val;

	atomic_set(&q.write_idx, 0);
	atomic_set(&q.read_idx, 0);

	spsc_push(&q, 0xAB);
	spsc_push(&q, 0xCD);

	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", (unsigned int)val);
	}
	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", (unsigned int)val);
	}
	if (spsc_pop(&q, &val) != 0) {
		printk("Queue empty as expected\n");
	}

	return 0;
}

/*
 * Lock-free SPSC ring queue for Zephyr RTOS.
 * Power-of-2 buffer with atomic indices — no locks required.
 */

#include <stdint.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>

#define QUEUE_SIZE 16U
#define QUEUE_MASK (QUEUE_SIZE - 1U)

#if (QUEUE_SIZE == 0U) || ((QUEUE_SIZE & QUEUE_MASK) != 0U)
#error "QUEUE_SIZE must be a power of two"
#endif

struct spsc_queue {
	uint8_t  buf[QUEUE_SIZE];
	atomic_t write_idx;
	atomic_t read_idx;
};

static struct spsc_queue q;

static int spsc_push(struct spsc_queue *q, uint8_t val)
{
	/* Unsigned arithmetic keeps counter wraparound well-defined. */
	uint32_t w = (uint32_t)atomic_get(&q->write_idx);
	uint32_t r = (uint32_t)atomic_get(&q->read_idx);

	/* Monotonic counters allow all QUEUE_SIZE slots to be used. */
	if ((uint32_t)(w - r) >= QUEUE_SIZE) {
		return -1; /* full */
	}

	q->buf[w & QUEUE_MASK] = val;

	/* Zephyr atomic operations provide the required memory barriers. */
	atomic_set(&q->write_idx, (atomic_val_t)(uint32_t)(w + 1U));
	return 0;
}

static int spsc_pop(struct spsc_queue *q, uint8_t *val)
{
	uint32_t r = (uint32_t)atomic_get(&q->read_idx);
	uint32_t w = (uint32_t)atomic_get(&q->write_idx);

	if (r == w) {
		return -1; /* empty */
	}

	*val = q->buf[r & QUEUE_MASK];

	/* Publish the free slot only after its contents have been read. */
	atomic_set(&q->read_idx, (atomic_val_t)(uint32_t)(r + 1U));
	return 0;
}

int main(void)
{
	uint8_t val;

	atomic_set(&q.write_idx, 0);
	atomic_set(&q.read_idx, 0);

	spsc_push(&q, 0xAB);
	spsc_push(&q, 0xCD);

	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", val);
	}
	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", val);
	}
	if (spsc_pop(&q, &val) != 0) {
		printk("Queue empty as expected\n");
	}

	return 0;
}

#include <zephyr/kernel.h>

#define CRC16_CCITT_POLY  0x1021U
#define CRC16_CCITT_INIT  0xFFFFU
#define TEST_BUF_SIZE    16U

static uint16_t crc16_ccitt(const uint8_t *data, uint16_t len)
{
    uint16_t crc = CRC16_CCITT_INIT;

    for (uint16_t i = 0; i < len; i++) {
        crc ^= (uint16_t)((uint16_t)data[i] << 8);
        for (uint8_t bit = 0; bit < 8; bit++) {
            if (crc & 0x8000U) {
                crc = (crc << 1) ^ CRC16_CCITT_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main(void)
{
    static const uint8_t test_buf[TEST_BUF_SIZE] = {
        0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38,
        0x39, 0x3A, 0x3B, 0x3C, 0x3D, 0x3E, 0x3F, 0x40,
    };

    uint16_t result = crc16_ccitt(test_buf, TEST_BUF_SIZE);

    printk("CRC-16-CCITT: 0x%04X\n", (unsigned int)result);
    return 0;
}

