#include <zephyr/kernel.h>
#include <psa/crypto.h>
#include <string.h>

#define AES_KEY_SIZE 32
#define AES_BLOCK_SIZE 16

static const uint8_t aes_key[AES_KEY_SIZE] = {
	0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
	0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
	0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
	0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
};

static const uint8_t plaintext[AES_BLOCK_SIZE] = {
	'H', 'e', 'l', 'l', 'o', ' ', 'Z', 'e',
	'p', 'h', 'y', 'r', '!', 0x00, 0x00, 0x00,
};

int main(void)
{
	psa_status_t status;
	psa_key_id_t key_id;
	psa_key_attributes_t attributes = PSA_KEY_ATTRIBUTES_INIT;
	uint8_t ciphertext[AES_BLOCK_SIZE + AES_BLOCK_SIZE];
	uint8_t decrypted[AES_BLOCK_SIZE];
	size_t output_len;

	status = psa_crypto_init();
	if (status != PSA_SUCCESS) {
		printk("PSA crypto init failed: %d\n", status);
		return -1;
	}

	psa_set_key_type(&attributes, PSA_KEY_TYPE_AES);
	psa_set_key_bits(&attributes, 256);
	psa_set_key_algorithm(&attributes, PSA_ALG_CBC_NO_PADDING);
	psa_set_key_usage_flags(&attributes,
				PSA_KEY_USAGE_ENCRYPT | PSA_KEY_USAGE_DECRYPT);

	status = psa_import_key(&attributes, aes_key, sizeof(aes_key), &key_id);
	if (status != PSA_SUCCESS) {
		printk("Key import failed: %d\n", status);
		return -1;
	}

	status = psa_cipher_encrypt(key_id, PSA_ALG_CBC_NO_PADDING,
				     plaintext, sizeof(plaintext),
				     ciphertext, sizeof(ciphertext),
				     &output_len);
	if (status != PSA_SUCCESS) {
		printk("Encryption failed: %d\n", status);
		psa_destroy_key(key_id);
		return -1;
	}

	status = psa_cipher_decrypt(key_id, PSA_ALG_CBC_NO_PADDING,
				     ciphertext, output_len,
				     decrypted, sizeof(decrypted),
				     &output_len);
	if (status != PSA_SUCCESS) {
		printk("Decryption failed: %d\n", status);
		psa_destroy_key(key_id);
		return -1;
	}

	if (memcmp(plaintext, decrypted, sizeof(plaintext)) == 0) {
		printk("AES-256-CBC encrypt/decrypt OK\n");
	} else {
		printk("AES-256-CBC verify FAILED\n");
	}

	psa_destroy_key(key_id);
	return 0;
}

#include <errno.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/sensor.h>

int main(void)
{
	const struct device *const dev = DEVICE_DT_GET(DT_NODELABEL(temp_sensor));
	struct sensor_value temp;
	int ret;

	if (!device_is_ready(dev)) {
		printk("Sensor device not ready\n");
		return -ENODEV;
	}

	while (1) {
		ret = sensor_sample_fetch(dev);
		if (ret < 0) {
			printk("Sensor fetch failed: %d\n", ret);
			k_sleep(K_SECONDS(2));
			continue;
		}

		ret = sensor_channel_get(dev, SENSOR_CHAN_AMBIENT_TEMP, &temp);
		if (ret < 0) {
			printk("Channel get failed: %d\n", ret);
			k_sleep(K_SECONDS(2));
			continue;
		}

		printk("Temperature: %d.%06d C\n", temp.val1, temp.val2);
		k_sleep(K_SECONDS(2));
	}

	return 0;
}

#include <zephyr/kernel.h>

struct data_item {
	uint32_t value;
};

K_MSGQ_DEFINE(my_msgq, sizeof(struct data_item), 10, 4);

void producer_entry(void *p1, void *p2, void *p3)
{
	struct data_item msg;
	uint32_t count = 0;

	while (1) {
		msg.value = count++;
		if (k_msgq_put(&my_msgq, &msg, K_NO_WAIT) == 0) {
			printk("Producer sent: %u\n", msg.value);
		}
		k_sleep(K_MSEC(100));
	}
}

void consumer_entry(void *p1, void *p2, void *p3)
{
	struct data_item msg;

	while (1) {
		if (k_msgq_get(&my_msgq, &msg, K_FOREVER) == 0) {
			printk("Consumer received: %u\n", msg.value);
		}
	}
}

K_THREAD_DEFINE(producer, 1024, producer_entry, NULL, NULL, NULL, 5, 0, 0);
K_THREAD_DEFINE(consumer, 1024, consumer_entry, NULL, NULL, NULL, 6, 0, 0);

int main(void)
{
	k_sleep(K_FOREVER);
	return 0;
}

#include <zephyr/kernel.h>

static volatile int counter;

void timer_expiry(struct k_timer *timer)
{
	counter++;
}

K_TIMER_DEFINE(my_timer, timer_expiry, NULL);

int main(void)
{
	k_timer_start(&my_timer, K_MSEC(500), K_MSEC(500));

	while (1) {
		printk("Counter: %d\n", counter);
		k_sleep(K_SECONDS(2));
	}

	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/watchdog.h>

static const struct device *wdt;
static int wdt_channel_id;

static void wdt_feed_timer_cb(struct k_timer *timer)
{
	wdt_feed(wdt, wdt_channel_id);
}

K_TIMER_DEFINE(wdt_feed_timer, wdt_feed_timer_cb, NULL);

int main(void)
{
	wdt = DEVICE_DT_GET(DT_ALIAS(watchdog0));

	if (!device_is_ready(wdt)) {
		printk("Watchdog not ready\n");
		return -1;
	}

	struct wdt_timeout_cfg wdt_cfg = {
		.flags = WDT_FLAG_RESET_SOC,
		.window.min = 0,
		.window.max = 3000,
		.callback = NULL,
	};

	wdt_channel_id = wdt_install_timeout(wdt, &wdt_cfg);
	if (wdt_channel_id < 0) {
		printk("WDT install failed: %d\n", wdt_channel_id);
		return -1;
	}

	int err = wdt_setup(wdt, WDT_OPT_PAUSE_HALTED_BY_DBG);

	if (err < 0) {
		printk("WDT setup failed: %d\n", err);
		return -1;
	}

	/* Timer period (1s) is shorter than WDT timeout (3s). */
	k_timer_start(&wdt_feed_timer, K_SECONDS(1), K_SECONDS(1));

	while (1) {
		printk("System heartbeat\n");
		k_sleep(K_SECONDS(5));
	}

	return 0;
}

